css:
.atlas{--bg:#f3eedc;--paper:#fbf8ec;--ink:#18180f;--muted:#6f6a52;--line:#cfc6a8;--nut:#856a12;--nut2:#b79a36;--deep:#252a18;--green:#56623a;--blue:#4b6470;--red:#8b4b34;--shadow:0 16px 44px rgba(37,32,14,.08)min-height:100vh;}
@media(prefers-color-scheme:dark){.atlas{--bg:#0d100b;--paper:#141810;--ink:#f3ecd0;--muted:#aaa287;--line:#353a2d;--nut:#d8ba4a;--nut2:#a88e31;--deep:#e8e1c5;--green:#9cad6d;--blue:#8aa8b4;--red:#d38a69;--shadow:none}}
*{box-sizing:border-box}html{scroll-behavior:smooth}.atlas{background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit}.page{max-width:1500px;margin:0 auto;padding:clamp(18px,3.5vw,52px)}
.top{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(240px,.65fr);gap:28px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:28px}.eyebrow{font-size:12px;font-weight:900;letter-spacing:.2em;text-transform:uppercase;color:var(--nut);margin-bottom:12px}.top h1{font-size:clamp(54px,9.4vw,132px);line-height:.8;letter-spacing:-.065em;margin:0;font-weight:1000;max-width:1050px}.dek{font-size:clamp(17px,1.7vw,23px);line-height:1.35;max-width:820px;margin:21px 0 0;color:var(--muted)}.scope{font-size:13px;line-height:1.6;color:var(--muted);border-left:3px solid var(--nut);padding-left:15px}.scope strong{color:var(--ink)}
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line);margin:22px 0 0}.stat{background:var(--paper);padding:15px 16px}.stat b{display:block;font-size:clamp(25px,3.4vw,45px);letter-spacing:-.045em}.stat span{display:block;margin-top:4px;font-size:10px;font-weight:850;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
.section{margin-top:42px}.section-head{display:flex;gap:14px;align-items:end;justify-content:space-between;flex-wrap:wrap;margin-bottom:13px}.section-head h2{font-size:clamp(27px,3.3vw,44px);letter-spacing:-.045em;margin:0}.section-head p{margin:0;color:var(--muted);font-size:13px;max-width:660px;line-height:1.45}
.atlas{background:var(--paper);border:1px solid var(--line);box-shadow:var(--shadow)}.tabs{position:absolute;right:12px;top:12px;z-index:8;display:grid;gap:6px;width:min(220px,calc(100% - 24px));padding:9px;background:color-mix(in srgb,var(--paper) 94%,transparent);border:1px solid var(--line);border-radius:10px;backdrop-filter:blur(10px);box-shadow:0 8px 26px rgba(0,0,0,.08)}.layer-title{padding:2px 4px 5px;font-size:9px;font-weight:950;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}.tab{display:flex;align-items:center;gap:9px;width:100%;min-height:38px;border:1px solid transparent;border-radius:7px;padding:8px 10px;background:transparent;color:var(--ink);font:inherit;font-size:11px;font-weight:900;letter-spacing:.035em;cursor:pointer;text-align:left}.tab:before{content:'';width:10px;height:10px;border-radius:50%;border:1px solid var(--line);background:transparent;flex:0 0 auto}.tab[aria-selected="true"]{background:color-mix(in srgb,var(--nut) 12%,var(--paper));border-color:var(--line)}.tab[aria-selected="true"]:before{background:var(--nut);border-color:var(--nut)}.atlas-body{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,.62fr);min-height:590px}.map-side{min-width:0;border-right:1px solid var(--line)}.map-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:11px;border-bottom:1px solid var(--line)}.map-tools label{font-size:10px;font-weight:900;letter-spacing:.12em;color:var(--muted);text-transform:uppercase}.map-tools select{min-height:42px;border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:8px;padding:6px 32px 6px 10px;font:inherit;font-size:13px}.map-wrap{position:relative;min-height:520px;overflow:hidden;background:color-mix(in srgb,var(--paper) 83%,var(--bg))}.map-status{position:absolute;top:12px;left:12px;z-index:2;background:color-mix(in srgb,var(--paper) 92%,transparent);border:1px solid var(--line);border-radius:7px;padding:7px 9px;font-size:11px;color:var(--muted);backdrop-filter:blur(8px)}#us-map{display:block;width:100%;height:520px}.density-view{position:absolute;inset:0;display:none;background:#eee9dc;overflow:hidden;pointer-events:none}.density-view.active{display:grid;place-items:center}.density-view img{display:block;width:100%;height:100%;object-fit:contain;opacity:0;transition:opacity .18s ease;background:#eee9dc}.density-view.ready img{opacity:1}.density-view #density-borders{display:none}.density-state{fill:none;stroke:color-mix(in srgb,var(--ink) 34%,transparent);stroke-width:.7}.density-loading{position:absolute;left:12px;top:12px;display:block;padding:8px 10px;background:color-mix(in srgb,var(--paper) 94%,transparent);border:1px solid var(--line);border-radius:7px;font-size:10px;font-weight:950;letter-spacing:.08em;color:var(--muted);z-index:3}.density-loading.hidden{display:none}.density-legend{position:absolute;left:12px;bottom:12px;z-index:4;display:flex;align-items:center;gap:10px;max-width:520px;padding:8px 10px;background:color-mix(in srgb,var(--paper) 94%,transparent);border:1px solid var(--line);border-radius:7px;font-size:9px;letter-spacing:.08em;backdrop-filter:blur(8px)}.density-legend span{color:var(--muted);text-transform:uppercase}.density-legend b{font-size:9px}.state{fill:color-mix(in srgb,var(--paper) 62%,var(--line));stroke:var(--paper);stroke-width:1}.state.has{fill:color-mix(in srgb,var(--nut) 26%,var(--paper))}.state.mast{fill:color-mix(in srgb,var(--green) 48%,var(--paper))}.state.dim{opacity:.28}.dot{stroke:var(--paper);stroke-width:2;cursor:pointer}.dot:hover,.dot.active{stroke:var(--ink);stroke-width:3}.farm-dot{fill:var(--red);stroke:var(--paper);stroke-width:2.5;cursor:pointer}.farm-dot:hover,.farm-dot.active{stroke:var(--ink);stroke-width:3.5}.map-label{font-size:10px;font-weight:950;fill:var(--ink);paint-order:stroke;stroke:var(--paper);stroke-width:3px;stroke-linejoin:round}.details{padding:18px;min-width:0}.details .kicker{font-size:10px;font-weight:950;letter-spacing:.13em;text-transform:uppercase;color:var(--nut)}.details h3{font-size:clamp(24px,3vw,39px);line-height:1;letter-spacing:-.045em;margin:7px 0 10px}.details .big{font-size:clamp(30px,4vw,52px);font-weight:1000;letter-spacing:-.055em}.details .sub{font-size:13px;color:var(--muted);line-height:1.45;margin-top:4px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);margin-top:18px}.detail-cell{background:var(--paper);padding:11px}.detail-cell b{display:block;font-size:18px}.detail-cell span{font-size:9px;text-transform:uppercase;letter-spacing:.11em;color:var(--muted);font-weight:850}.source-link{display:inline-flex;align-items:center;gap:7px;margin-top:16px;border-bottom:1px solid currentColor;text-decoration:none;font-size:12px;font-weight:900;color:var(--nut)}
.territory-maps{display:none;padding:18px;gap:12px;grid-template-columns:repeat(3,minmax(0,1fr));height:520px}.territory-map{border:1px solid var(--line);border-radius:10px;padding:10px;min-width:0;display:flex;flex-direction:column}.territory-map b{font-size:11px;text-transform:uppercase;letter-spacing:.1em}.territory-map svg{width:100%;flex:1;min-height:0}.coast{fill:color-mix(in srgb,var(--paper) 55%,var(--line));stroke:var(--line);stroke-width:.5}.territory-pin{fill:var(--nut);stroke:var(--paper);stroke-width:2}.territory-name{font-size:9px;font-weight:950;fill:var(--ink);paint-order:stroke;stroke:var(--paper);stroke-width:3px}
.ledger-tools{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.filter-btn{min-height:40px;border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:999px;padding:8px 12px;font:inherit;font-size:11px;font-weight:900;cursor:pointer}.filter-btn.active{background:var(--ink);color:var(--paper)}.table-wrap{overflow:auto;border:1px solid var(--line);background:var(--paper)}table{border-collapse:collapse;width:100%;min-width:900px;font-size:12px}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line);vertical-align:top}th{position:sticky;top:0;background:var(--paper);font-size:9px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);z-index:1}td.num{font-variant-numeric:tabular-nums;font-weight:800}.value{font-weight:1000}.src{font-weight:900;color:var(--nut);text-decoration:none;border-bottom:1px solid currentColor}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:3px 7px;font-size:9px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}
.territories{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.territory-card{background:var(--paper);border:1px solid var(--line);padding:15px;min-width:0}.territory-card .flag{font-size:10px;font-weight:950;color:var(--nut);letter-spacing:.12em;text-transform:uppercase}.territory-card h3{font-size:20px;letter-spacing:-.035em;margin:5px 0 14px}.territory-card .metric{border-top:1px solid var(--line);padding:9px 0}.territory-card .metric b{display:block;font-size:19px;letter-spacing:-.025em}.territory-card .metric span{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin-top:2px}.territory-card p{font-size:11px;color:var(--muted);line-height:1.4;margin:9px 0 0}.footnote{font-size:10px;line-height:1.45;color:var(--muted);margin-top:9px}
.growers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.grower{background:var(--paper);border:1px solid var(--line);padding:15px}.grower .crop{font-size:10px;font-weight:950;color:var(--nut);letter-spacing:.12em;text-transform:uppercase}.grower h3{font-size:18px;margin:5px 0 7px;letter-spacing:-.025em}.grower address{font-style:normal;font-size:11px;color:var(--muted);line-height:1.4}.grower .datum{margin-top:13px;padding-top:10px;border-top:1px solid var(--line);font-size:11px;line-height:1.45}.grower .datum b{font-size:16px}.grower a{display:inline-block;margin-top:10px;font-size:11px;font-weight:900;color:var(--nut);text-decoration:none;border-bottom:1px solid currentColor}
.mast-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.mast-card{background:var(--paper);border:1px solid var(--line);padding:15px}.mast-card h3{font-size:18px;margin:0 0 5px}.mast-card .latin{font-size:10px;color:var(--muted);font-style:italic}.mast-card p{font-size:11px;color:var(--muted);line-height:1.45;margin:9px 0}.mast-card a{font-size:11px;font-weight:900;color:var(--nut);text-decoration:none;border-bottom:1px solid currentColor}.mast-card .type{display:inline-block;margin-bottom:8px;font-size:8px;font-weight:950;letter-spacing:.12em;color:var(--green);text-transform:uppercase}.mast-surveys{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.mast-surveys article{border:1px solid var(--line);background:var(--paper);padding:16px}.mast-surveys h3{margin:5px 0 8px;font-size:18px}.mast-surveys b{font-size:20px}.mast-surveys p{font-size:11px;color:var(--muted);line-height:1.5}.mast-surveys a{font-size:11px;font-weight:900;color:var(--nut);text-decoration:none;border-bottom:1px solid currentColor}.survey-tag{font-size:9px;font-weight:950;letter-spacing:.12em;color:var(--nut)}.footer{border-top:1px solid var(--line);margin-top:44px;padding:18px 0 0;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:10px;color:var(--muted)}
@media(max-width:1000px){.top{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.atlas-body{grid-template-columns:1fr}.map-side{border-right:0;border-bottom:1px solid var(--line)}.territories,.growers{grid-template-columns:repeat(2,minmax(0,1fr))}.mast-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.territory-maps{grid-template-columns:1fr 1fr;height:auto}.territory-map{min-height:260px}}
@media(max-width:700px){.mast-surveys{grid-template-columns:1fr}}
@media(max-width:620px){.tabs{right:8px;top:8px;width:178px;padding:7px}.tab{min-height:34px;padding:7px 8px;font-size:9px}.layer-title{font-size:8px}.page{padding:14px}.top h1{font-size:56px}.stats{grid-template-columns:1fr 1fr}.stat{padding:12px}.atlas-body{min-height:0}.map-wrap,#us-map{height:400px;min-height:400px}.territory-maps{grid-template-columns:1fr}.territories,.growers,.mast-grid{grid-template-columns:1fr}.details{padding:15px}.tab{padding:9px 11px}.section{margin-top:30px}}
